// Generated by Launchpad (recipe vercel-queue). Moves the messages this
// queue left in pg-boss's default schema, "pgboss", before it kept them in a
// schema of its own, "launchpad_queue": the Workflow SDK's Postgres backend drops
// any schema called "pgboss", and with it whatever is still waiting there.
//
// Only this queue's own topics are moved, so an app that uses pg-boss itself
// keeps its own jobs. The queue worker runs it as it starts and every minute
// after; the Workflow SDK's setup runs it before the backend's own setup.

// The topics this queue delivers, from vercel.json.
const TOPICS = ["send-email"];

// drainOldQueue answers how many messages it moved. With no pg-boss given it
// starts one of its own on the app's database, and stops it after.
export async function drainOldQueue(boss) {
  const own = !boss;
  if (own) {
    const mod = await import("pg-boss");
    const PgBoss = mod.PgBoss ?? mod.default ?? mod;
    boss = new PgBoss({ connectionString: process.env.DATABASE_URL, schema: "launchpad_queue", supervise: false, schedule: false });
    boss.on("error", (e) => console.error("queue:", e.message));
    await boss.start();
  }
  try {
    const db = boss.getDb();
    const found = await db.executeSql(
      "select exists (select 1 from information_schema.tables where table_schema = 'pgboss' and table_name = 'job') as found",
    );
    if (!found.rows[0]?.found) return 0;
    const waiting = await db.executeSql(
      "select id, name, data, start_after, singleton_key from pgboss.job where state in ('created', 'retry') and name = any($1)",
      [TOPICS],
    );
    for (const job of waiting.rows) {
      if (boss.createQueue) await boss.createQueue(job.name, { retryLimit: 5, expireInSeconds: 960 }).catch(() => {});
      await boss.send(job.name, job.data, { startAfter: job.start_after, singletonKey: job.singleton_key ?? undefined });
      await db.executeSql("delete from pgboss.job where id = $1", [job.id]);
    }
    if (waiting.rows.length) {
      console.log(`queue: moved ${waiting.rows.length} waiting message(s) from the old "pgboss" schema to "launchpad_queue"`);
    }
    return waiting.rows.length;
  } finally {
    if (own) await boss.stop({ graceful: false }).catch(() => {});
  }
}
